using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.U2D.Sprites;
using UnityEngine;
using Newtonsoft.Json.Linq;

public static class ImportArmedGrip20261001
{
    const string Root=RuinRunner.NativeHeroFrameCatalog.SourceRoot+"ArmedGripV3/";
    static bool CoveredGrip(string path,Vector2 grip)
    {
        var t=new Texture2D(2,2,TextureFormat.RGBA32,false);t.LoadImage(File.ReadAllBytes(path));var p=t.GetPixels32();bool visible=false;
        for(int y=Mathf.Max(0,Mathf.FloorToInt(grip.y)-1);y<=Mathf.Min(63,Mathf.FloorToInt(grip.y)+1);y++)
        for(int x=Mathf.Max(0,Mathf.FloorToInt(grip.x)-1);x<=Mathf.Min(47,Mathf.FloorToInt(grip.x)+1);x++)
        {var c=p[(63-y)*48+x];if(c.a>0&&(c.r==229&&c.g==149&&c.b==159||c.r==193&&c.g==106&&c.b==125))visible=true;}
        UnityEngine.Object.DestroyImmediate(t);return !visible;
    }
    public static string Main()
    {
        if(Application.isPlaying)throw new Exception("Stop Play Mode");
        if(Directory.Exists(Root))throw new Exception("Existing import must be preserved");
        var data=JObject.Parse(File.ReadAllText("ArtDirection/Generated/SscaryMotion-20261001/armed-grip-v3/manifest.json",Encoding.UTF8));
        var paths=new List<string>();var cells=new List<int>();var hands=new List<Vector2>();var rows=new JArray();var behind=new List<bool>();
        Directory.CreateDirectory(Root);int unique=data.Value<int>("uniqueSprites");
        for(int index=0;index<unique;index++){string path=Root+index.ToString("D5")+".png";File.Copy("ArtDirection/Generated/SscaryMotion-20261001/armed-grip-v3/"+index.ToString("D5")+".png",path);paths.Add(path);}
        foreach(JObject row in data["frames"])
        {
            int index=row.Value<int>("runtimeIndex");var hand=new Vector2((float)row["grip"][0],(float)row["grip"][1]);cells.Add(index);hands.Add(hand);bool covered=CoveredGrip(row.Value<string>("path"),hand);behind.Add(covered);
            var adopted=(JObject)row.DeepClone();adopted["runtimePath"]=paths[index];adopted["handBehindBody"]=covered;rows.Add(adopted);
        }
        AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
        AssetDatabase.StartAssetEditing();
        try
        {
            foreach(var path in paths)
            {
                var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;
                imp.spritePixelsPerUnit=32;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;
                imp.npotScale=TextureImporterNPOTScale.None;imp.wrapMode=TextureWrapMode.Clamp;imp.alphaIsTransparency=true;imp.isReadable=false;
                var setting=new TextureImporterSettings();imp.ReadTextureSettings(setting);setting.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(setting);
                AssetDatabase.WriteImportSettingsIfDirty(path);AssetDatabase.ImportAsset(path);
            }
        }finally{AssetDatabase.StopAssetEditing();}
        var factories=new SpriteDataProviderFactories();factories.Init();AssetDatabase.StartAssetEditing();
        try
        {
            foreach(var path in paths)
            {
                var imp=(TextureImporter)AssetImporter.GetAtPath(path);var provider=factories.GetSpriteEditorDataProviderFromObject(imp);provider.InitSpriteEditorDataProvider();
                var cap=provider.GetDataProvider<ISpriteFrameEditCapability>();if(cap==null||!cap.GetEditCapability().HasCapability(EEditCapability.EditPivot))throw new Exception("Pivot capability "+path);
                var rects=provider.GetSpriteRects();if(rects.Length!=1)throw new Exception(path);
                rects[0].alignment=SpriteAlignment.Custom;rects[0].pivot=new Vector2(.5f,22/64f);provider.SetSpriteRects(rects);provider.Apply();
                AssetDatabase.WriteImportSettingsIfDirty(path);AssetDatabase.ImportAsset(path);
            }
        }finally{AssetDatabase.StopAssetEditing();}
        foreach(var path in paths){var sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path);if(sprite==null||sprite.rect.width!=48||sprite.rect.height!=64||sprite.pixelsPerUnit!=32||sprite.pivot!=new Vector2(24,22))throw new Exception("Import geometry "+path);}
        var code=new StringBuilder("// Native armed-joint revision; original face/pack/gait and clocks retained. Generated by ImportArmedGrip20261001.\nusing UnityEngine;\nnamespace RuinRunner\n{\n public static class SscaryArmedFrames\n {\n");
        code.Append(" public const string Root=\"External/SscaryMaleCombat/ArmedGripV3\";\n public const int UniqueSpriteCount=").Append(paths.Count).Append(";\n private static Sprite[] frames;\n private static readonly int[] DirectionRows={0,1,2,2,3,4,4,5},Clips={2,3,2,1,4,6},Variants={16,16,16,9,16,16},Keys={1,16,16,16,16,16};\n");
        code.Append(" private static readonly int[] Cells={");foreach(var cell in cells)code.Append(cell).Append(',');code.Append("};\n");
        code.Append(" private static readonly Vector2[] Hands={");foreach(var h in hands)code.Append("new Vector2(").Append(h.x.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append("f,").Append(h.y.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append("f),");code.Append("};\n");
        code.Append(" private static readonly bool[] Behind={");foreach(var value in behind)code.Append(value?"true,":"false,");code.Append("};\n");
        code.Append(" public static void Preload(){if(frames==null)frames=Load();}\n static Sprite[] Load(){var result=new Sprite[UniqueSpriteCount];for(int i=0;i<result.Length;i++)result[i]=IndividualArt.Sprite(Root+\"/\"+i.ToString(\"D5\"));return result;}\n");
        code.Append(" static Sprite Pick(int kind,int clip,int direction,int variant,int key,out Vector2 hand,out bool behind){Preload();int offset=0;for(int i=0;i<kind;i++)offset+=Clips[i]*6*Variants[i]*Keys[i];int slot=offset+((Mathf.Clamp(clip,0,Clips[kind]-1)*6+DirectionRows[Mathf.Clamp(direction,0,7)])*Variants[kind]+Mathf.Clamp(variant,0,Variants[kind]-1))*Keys[kind]+Mathf.Clamp(key,0,Keys[kind]-1);hand=Hands[slot];behind=Behind[slot];return frames[Cells[slot]];}\n");
        code.Append(" public static Sprite Carry(bool twoHand,int d,int v,out Vector2 h,out bool b)=>Pick(0,twoHand?1:0,d,v,0,out h,out b);\n public static Sprite Melee(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(1,c,d,v,k,out h,out b);\n public static Sprite Short(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(2,c,d,v,k,out h,out b);\n public static Sprite Thrust(int d,int gait,int k,out Vector2 h){bool b;return Pick(3,0,d,gait+1,k,out h,out b);}\n public static Sprite Defense(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(4,c,d,v,k,out h,out b);\n public static Sprite Ranged(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(5,c,d,v,k,out h,out b);\n }\n}\n");
        File.WriteAllText("Assets/RuinRunner/Runtime/Player/SscaryArmedFrames.cs",code.ToString(),new UTF8Encoding(false));
        File.WriteAllText("ArtDirection/Review-20261001/weapon-carry/native-import-v3.json",new JObject{{"uniqueSprites",paths.Count},{"sampleSlots",cells.Count},{"standUnique",data["standUnique"]},{"scope","Same existing native pose/gait clocks; raised and extended grip joints. These combinations are not new authored poses."},{"frames",rows}}.ToString(),new UTF8Encoding(false));
        AssetDatabase.SaveAssets();AssetDatabase.Refresh();return paths.Count+" unique native revised sprites; "+cells.Count+" combinations, fixed48x64/(24,22)/32PPU/Point/uncompressed.";
    }
}
